UPDATE marketing_rules
name = #{name}, trigger_type = #{triggerType}, trigger_days = #{triggerDays}, customer_filter = #{customerFilter}, notification_type = #{notificationType}, template_id = #{templateId}, custom_subject = #{customSubject}, custom_content = #{customContent}, schedule_type = #{scheduleType}, schedule_time = #{scheduleTime}, schedule_day_of_week = #{scheduleDayOfWeek}, cooldown_days = #{cooldownDays}, updated_at = UTC_TIMESTAMP(), updated_by = #{updatedBy},
WHERE id = #{id}

UPDATE marketing_rules
SET last_run_at = UTC_TIMESTAMP(), total_sent_count = total_sent_count + #{sentCount}
WHERE id = #{id}
